import sqlite3

from booking.models import Booking, BookingCreate, Room, RoomCreate


class NotFoundError(Exception):
    pass


class ConflictError(Exception):
    pass


class Storage:
    def __init__(self, db_path: str) -> None:
        self.db = sqlite3.connect(db_path, check_same_thread=False)
        self.db.row_factory = sqlite3.Row
        with self.db:
            self.db.executescript((
                    "\n            CREATE TABLE IF NOT EXISTS rooms(\n                id INTEGER PR"
                "IMARY KEY,\n                name TEXT UNIQUE,\n                capacity INTEGE"
                "R\n            );\n            CREATE TABLE IF NOT EXISTS bookings(\n         "
                "       id INTEGER PRIMARY KEY,\n                room_id INTEGER,\n            "
                "    title TEXT,\n                start TEXT,\n                end TEXT\n      "
                "      );\n        "))

    def create_room(self, data: RoomCreate) -> Room:
        try:
            cursor = self.db.execute("INSERT INTO rooms (name, capacity) VALUES (:name, :capacity)",
                {"name": data.name, "capacity": data.capacity})
            self.db.commit()
            return self.get_room(cursor.lastrowid or 0)
        except sqlite3.IntegrityError as e:
            raise ConflictError("Room already exists") from e

    def get_room(self, room_id: int) -> Room:
        cursor = self.db.cursor()
        cursor.execute("SELECT * FROM rooms WHERE id = ?", (room_id,))
        row = cursor.fetchone()
        if row is None:
            raise NotFoundError('room not found')
        return Room(**dict(row))

    def list_rooms(self) -> list[Room]:
        return [Room(**dict(row)) for row in self.db.execute("SELECT * FROM rooms ORDER BY id")]

    def create_booking(self, data: BookingCreate) -> Booking:
        room = self.get_room(data.room_id)
        if room is None:
            raise NotFoundError(f"Room with ID {data.room_id} not found")
        cursor = self.db.cursor()
        start, end = data.start.isoformat(), data.end.isoformat()
        cursor.execute("SELECT * FROM bookings WHERE room_id = ? AND start < ? AND end > ?",
            (data.room_id, end, start),)
        if cursor.fetchone() is not None:
            raise ConflictError("overlap")
        cursor.execute("INSERT INTO bookings (room_id, title, start, end) VALUES (?, ?, ?, ?)",
            (data.room_id, data.title, start, end),)
        self.db.commit()
        return Booking(id=int(cursor.lastrowid or 0), **data.model_dump())

    def list_bookings(self, room_id: int) -> list[Booking]:
        # Retrieve the room and then select its bookings
        room = self.get_room(room_id)
        if room is None:
            raise NotFoundError(f"Room with ID {room_id} not found")
        bookings = self.db.execute(
            "SELECT * FROM bookings WHERE room_id = ? ORDER BY start", (room.id,))
        return [Booking(**dict(row)) for row in bookings]

    def delete_booking(self, booking_id: int) -> None:
        cursor = self.db.cursor()
        cursor.execute("DELETE FROM bookings WHERE id = ?", (booking_id,))
        self.db.commit()
        if cursor.rowcount == 0:
            raise NotFoundError('booking not found')

openapi: 3.1.0
info: {title: Meeting Room Booking API, version: 1.0.0}
paths:
  /health:
    get:
      responses:
        '200':
          description: API is running
          content: {application/json: {schema: {type: object, required: [status], properties: {status: {type: string, enum: [ok]}}}}}
  /rooms:
    post:
      requestBody: {required: true, content: {application/json: {schema: {$ref: '#/components/schemas/RoomCreate'}}}}
      responses:
        '201': {description: Room created, content: {application/json: {schema: {$ref: '#/components/schemas/Room'}}}}
        '409': {$ref: '#/components/responses/Conflict'}
        '422': {$ref: '#/components/responses/ValidationError'}
    get:
      responses:
        '200': {description: List of rooms, content: {application/json: {schema: {type: array, items: {$ref: '#/components/schemas/Room'}}}}}
  /bookings:
    post:
      requestBody: {required: true, content: {application/json: {schema: {$ref: '#/components/schemas/BookingCreate'}}}}
      responses:
        '201': {description: Booking created, content: {application/json: {schema: {$ref: '#/components/schemas/Booking'}}}}
        '404': {$ref: '#/components/responses/NotFound'}
        '409': {$ref: '#/components/responses/Conflict'}
        '422': {$ref: '#/components/responses/ValidationError'}
  /rooms/{room_id}/bookings:
    get:
      parameters: [{name: room_id, in: path, required: true, schema: {type: integer}}]
      responses:
        '200': {description: Bookings sorted by start, content: {application/json: {schema: {type: array, items: {$ref: '#/components/schemas/Booking'}}}}}
        '404': {$ref: '#/components/responses/NotFound'}
  /bookings/{booking_id}:
    delete:
      parameters: [{name: booking_id, in: path, required: true, schema: {type: integer}}]
      responses:
        '204': {description: Booking cancelled; empty response body}
        '404': {$ref: '#/components/responses/NotFound'}
components:
  schemas:
    RoomCreate:
      type: object
      required: [name, capacity]
      properties: {name: {type: string}, capacity: {type: integer, minimum: 1}}
    Room:
      type: object
      required: [id, name, capacity]
      properties: {id: {type: integer}, name: {type: string}, capacity: {type: integer, minimum: 1}}
    BookingCreate:
      type: object
      description: Start must be before end; the room must exist and the interval must not overlap a booking of that room.
      required: [room_id, title, start, end]
      properties:
        room_id: {type: integer}
        title: {type: string, minLength: 1}
        start: {type: string, format: date-time}
        end: {type: string, format: date-time}
    Booking:
      type: object
      required: [id, room_id, title, start, end]
      properties:
        id: {type: integer}
        room_id: {type: integer}
        title: {type: string, minLength: 1}
        start: {type: string, format: date-time}
        end: {type: string, format: date-time}
    Error:
      type: object
      required: [detail]
      properties: {detail: {type: string}}
    ValidationError:
      type: object
      required: [detail]
      properties: {detail: {type: array, items: {type: object}}}
  responses:
    NotFound:
      description: Room or booking not found
      content: {application/json: {schema: {$ref: '#/components/schemas/Error'}}}
    Conflict:
      description: Room name already exists or booking overlaps
      content: {application/json: {schema: {$ref: '#/components/schemas/Error'}}}
    ValidationError:
      description: Invalid request body, empty title, capacity below 1, or start not before end
      content: {application/json: {schema: {$ref: '#/components/schemas/ValidationError'}}}
